    fun encodeReply(reply: McReply): String {
        val root = JSONObject().put("v", 1).put("id", reply.id)
        when (reply) {
            is McReply.Failure -> {
                root.put("ok", false).put("error", writeErrorPayload(reply.error))
            }

            is McReply.Success -> {
                root.put("ok", true).put(
                    "result",
                    when (val result = reply.result) {
                        is RemoteResult.StateGet -> {
                            writeRemoteSnapshot(result.value)
                        }

                        is RemoteResult.CapabilitiesGet -> {
                            writeCapabilities(result.value)
