    private fun readId(value: Any): String {
        val result = string(value)
        check(result.codePointCount(0, result.length) in 1..128)
        check(result.matches(Regex("^[A-Za-z0-9_-]+$")))
        return result
    }

    private fun writeId(value: String): Any = value

    private fun readDecimal(value: Any): String {
        val result = string(value)
        check(result.matches(Regex("0|[1-9][0-9]*")) && result.toULongOrNull() != null)
        return result
    }

    private fun writeDecimal(value: String): Any = value

    private fun readText(value: Any): String {
        val result = string(value)
        check(result.codePointCount(0, result.length) in 0..4096)
        return result
    }

    private fun writeText(value: String): Any = value

    private fun readQuery(value: Any): String {
        val result = string(value)
        check(result.codePointCount(0, result.length) in 0..200)
        return result
    }

    private fun writeQuery(value: String): Any = value

    private fun readLabel(value: Any): String {
        val result = string(value)
        check(result.codePointCount(0, result.length) in 1..64)
        return result
    }

    private fun writeLabel(value: String): Any = value

    private fun readCursor(value: Any): String {
        val result = string(value)
        check(result.codePointCount(0, result.length) in 0..2048)
        check(result.toByteArray(Charsets.UTF_8).size <= 2048)
        return result
    }

    private fun writeCursor(value: String): Any = value

    private fun readBool(value: Any): Boolean = value as? Boolean ?: invalid()

    private fun writeBool(value: Boolean): Any = value

    private fun readVolume(value: Any): Double {
        val result = number(value)
