    private fun readIdBatch(value: Any): IdBatch {
        val source = value as? JSONArray ?: invalid()
        check(source.length() in 1..100)
        val result = (0 until source.length()).map { readId(source.get(it)) }
        return result
    }

    private fun writeIdBatch(value: IdBatch): Any = JSONArray(value.map { writeId(it) })

    private fun readMediaKinds(value: Any): MediaKinds {
        val source = value as? JSONArray ?: invalid()
        check(source.length() in 1..3)
        val result = (0 until source.length()).map { readMediaKind(source.get(it)) }
        check(result.distinct().size == result.size)
        return result
    }

    private fun writeMediaKinds(value: MediaKinds): Any = JSONArray(value.map { writeMediaKind(it) })

