        val result = JSONObject()
        value.serverEpoch?.let { result.put("serverEpoch", writeId(it)) }
        value.sessionId?.let { result.put("sessionId", writeId(it)) }
        value.queueRevision?.let { result.put("queueRevision", writeDecimal(it)) }
        value.playlistRevision?.let { result.put("playlistRevision", writeDecimal(it)) }
        value.sourcesRevision?.let { result.put("sourcesRevision", writeDecimal(it)) }
