    private fun readPlaylistsSaveParams(value: Any): PlaylistsSaveParams {
        val source = obj(value)
        return when (string(source.get("action"))) {
            "save_queue" -> {
                PlaylistsSaveParams.SaveQueue(
                    name = readPlaylistName(source.get("name")),
                    playlistId =
                        if (source.isNull("playlistId")) {
                            null
                        } else {
                            readId(source.get("playlistId"))
                        },
                )
            }

            "append" -> {
                PlaylistsSaveParams.Append(
                    playlistId = readId(source.get("playlistId")),
                    itemIds = readIdBatch(source.get("itemIds")),
                )
            }

            "remove" -> {
                PlaylistsSaveParams.Remove(
                    playlistId = readId(source.get("playlistId")),
                    entryIds = readIdBatch(source.get("entryIds")),
                )
            }

            "rename" -> {
                PlaylistsSaveParams.Rename(
                    playlistId = readId(source.get("playlistId")),
                    name = readPlaylistName(source.get("name")),
                )
            }

            else -> {
                unsupported()
            }
        }
    }

    private fun writePlaylistsSaveParams(value: PlaylistsSaveParams): Any =
        when (value) {
            is PlaylistsSaveParams.SaveQueue -> {
                JSONObject().put("action", "save_queue").put("name", writePlaylistName(value.name)).apply {
                    value.playlistId?.let { put("playlistId", writeId(it)) }
                }
            }

            is PlaylistsSaveParams.Append -> {
                JSONObject()
                    .put(
                        "action",
                        "append",
                    ).put("playlistId", writeId(value.playlistId))
                    .put("itemIds", writeIdBatch(value.itemIds))
            }

            is PlaylistsSaveParams.Remove -> {
                JSONObject()
                    .put(
                        "action",
                        "remove",
                    ).put("playlistId", writeId(value.playlistId))
                    .put("entryIds", writeIdBatch(value.entryIds))
            }

            is PlaylistsSaveParams.Rename -> {
                JSONObject()
                    .put(
                        "action",
                        "rename",
                    ).put("playlistId", writeId(value.playlistId))
                    .put("name", writePlaylistName(value.name))
            }
        }

