    private fun readMinorVersion(value: Any): Int {
        val result = integer(value)
        check(result in 0L..65535L)
        return result.toInt()
    }

    private fun readTimestampMs(value: Any): Long {
        val result = integer(value)
        check(result in 0L..9007199254740991L)
        return result
    }

