    private fun readPairingPreparation(value: Any): PairingPreparation {
        val source = obj(value)
        return when (string(source.get("status"))) {
            "confirmation_required" -> {
                PairingPreparation.ConfirmationRequired(preview = readConfirmationPreview(source.get("preview")))
            }

            "ready" -> {
                PairingPreparation.Ready(
                    operationId = readId(source.get("operationId")),
                    candidate = readPairingCandidate(source.get("candidate")),
                )
            }

            "already_issued" -> {
                PairingPreparation.AlreadyIssued(operationId = readId(source.get("operationId")))
            }

            else -> {
                unsupported()
            }
        }
    }

    private fun writePairingPreparation(value: PairingPreparation): Any =
        when (value) {
            is PairingPreparation.ConfirmationRequired -> {
                JSONObject()
                    .put(
                        "status",
                        "confirmation_required",
                    ).put("preview", writeConfirmationPreview(value.preview))
            }

            is PairingPreparation.Ready -> {
                JSONObject()
                    .put(
                        "status",
                        "ready",
                    ).put(
                        "operationId",
                        writeId(value.operationId),
                    ).put("candidate", writePairingCandidate(value.candidate))
            }

            is PairingPreparation.AlreadyIssued -> {
                JSONObject().put("status", "already_issued").put("operationId", writeId(value.operationId))
            }
        }

    private fun readManualChallengeMode(value: Any): ManualChallengeMode =
        ManualChallengeMode.entries.firstOrNull { it.wire == string(value) } ?: unsupported()

    private fun writeManualChallengeMode(value: ManualChallengeMode): Any = value.wire

    private fun readManualChallengeRequest(value: Any): ManualChallengeRequest {
        val source = obj(value)
        return ManualChallengeRequest(
            v = readVersion(source.get("v")),
            mode = readManualChallengeMode(source.get("mode")),
        )
    }

    private fun writeManualChallengeRequest(value: ManualChallengeRequest): Any {
        val result = JSONObject()
        result.put("v", writeVersion(value.v))
        result.put("mode", writeManualChallengeMode(value.mode))
        return result
    }

    private fun readManualChallengeResponse(value: Any): ManualChallengeResponse {
        val source = obj(value)
        return ManualChallengeResponse(
            v = readVersion(source.get("v")),
            serverDeviceId = readId(source.get("serverDeviceId")),
            attemptId = readId(source.get("attemptId")),
        )
    }

    private fun writeManualChallengeResponse(value: ManualChallengeResponse): Any {
        val result = JSONObject()
        result.put("v", writeVersion(value.v))
        result.put("serverDeviceId", writeId(value.serverDeviceId))
        result.put("attemptId", writeId(value.attemptId))
        return result
    }

    private fun readForegroundAck(value: Any): ForegroundAck {
        val source = obj(value)
        return ForegroundAck(
            requestId = readId(source.get("requestId")),
        )
    }

    private fun writeForegroundAck(value: ForegroundAck): Any {
        val result = JSONObject()
        result.put("requestId", writeId(value.requestId))
        return result
    }

    fun parsePairingCandidate(input: String): PairingCandidate = safely { readPairingCandidate(document(input, 65536)) }

    fun encodePairingCandidate(value: PairingCandidate): String = writePairingCandidate(value).toString()

    fun parseManualPairingCandidate(input: String): ManualPairingCandidate =
        safely {
            readManualPairingCandidate(document(input, 65536))
        }

    fun encodeManualPairingCandidate(value: ManualPairingCandidate): String =
        writeManualPairingCandidate(value).toString()

    fun parsePairRequest(input: String): PairRequest = safely { readPairRequest(document(input, 65536)) }

    fun encodePairRequest(value: PairRequest): String = writePairRequest(value).toString()

    fun parseManualPairRequest(input: String): ManualPairRequest =
        safely { readManualPairRequest(document(input, 65536)) }

    fun encodeManualPairRequest(value: ManualPairRequest): String = writeManualPairRequest(value).toString()

    fun parsePairedMediacenter(input: String): PairedMediacenter =
        safely { readPairedMediacenter(document(input, 65536)) }

    fun encodePairedMediacenter(value: PairedMediacenter): String = writePairedMediacenter(value).toString()

    fun parseManualChallengeRequest(input: String): ManualChallengeRequest =
        safely {
            readManualChallengeRequest(document(input, 65536))
        }

    fun encodeManualChallengeRequest(value: ManualChallengeRequest): String =
        writeManualChallengeRequest(value).toString()

    fun parseManualChallengeResponse(input: String): ManualChallengeResponse =
        safely {
            readManualChallengeResponse(document(input, 65536))
        }

    fun encodeManualChallengeResponse(value: ManualChallengeResponse): String =
        writeManualChallengeResponse(value).toString()
}
